    pub state: &'static str,
    pub author: &'static str,
    pub draft: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Check {
    pub pull_request: u32,
    pub name: &'static str,
    pub status: &'static str,
}

const VIEWER: &str = "corpus-bot";

const REPOSITORIES: &[Repository] = &[
    Repository {
        name: "demo/alpha",
        description: "Alpha service",
        visibility: "public",
    },
    Repository {
        name: "demo/beta",
        description: "Beta tools",
        visibility: "private",
    },
];

const PULL_REQUESTS: &[PullRequest] = &[
    PullRequest {
        number: 1,
        title: "Add pager",
        state: "open",
        author: "alice",
        draft: false,
    },
    PullRequest {
        number: 2,
        title: "Fix theme",
        state: "merged",
        author: "bob",
        draft: false,
    },
    PullRequest {
        number: 3,
        title: "Docs pass",
        state: "open",
        author: "alice",
        draft: true,
    },
];

const CHECKS: &[Check] = &[
    Check {
        pull_request: 1,
        name: "build",
        status: "pass",
    },
    Check {
        pull_request: 1,
        name: "lint",
        status: "fail",
    },
    Check {
        pull_request: 2,
        name: "build",
        status: "pass",
    },
    Check {
        pull_request: 2,
        name: "lint",
        status: "pass",
    },
];

/// The one built-in forge this client reads.
#[derive(Clone, Copy, Debug, Default)]
pub struct Forge;

impl Forge {
    pub fn new() -> Self {
        Self
    }

    /// The authenticated user.
    pub fn viewer(&self) -> &'static str {
        VIEWER
    }

    pub fn repository(&self, name: &str) -> Option<&'static Repository> {
        REPOSITORIES.iter().find(|repo| repo.name == name)
    }

    pub fn pull_requests(&self) -> &'static [PullRequest] {
        PULL_REQUESTS
    }

    pub fn pull_request(&self, number: u32) -> Option<&'static PullRequest> {
        PULL_REQUESTS.iter().find(|pr| pr.number == number)
    }

    pub fn checks(&self, pull_request: u32) -> Vec<&'static Check> {
        CHECKS
            .iter()
            .filter(|check| check.pull_request == pull_request)
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn repositories_are_found_by_full_name() {
        let forge = Forge::new();
        assert_eq!(forge.repository("demo/alpha").unwrap().visibility, "public");
        assert_eq!(forge.repository("demo/beta").unwrap().visibility, "private");
        assert!(forge.repository("demo/gamma").is_none());
    }

    #[test]
    fn pull_requests_are_listed_in_number_order() {
        let forge = Forge::new();
        let numbers: Vec<u32> = forge.pull_requests().iter().map(|pr| pr.number).collect();
        assert_eq!(numbers, [1, 2, 3]);
    }

    #[test]
    fn pull_requests_are_found_by_number() {
        let forge = Forge::new();
        assert_eq!(forge.pull_request(2).unwrap().title, "Fix theme");
        assert!(forge.pull_request(9).is_none());
    }

    #[test]
    fn checks_keep_their_declared_order_per_pull_request() {
        let forge = Forge::new();
        let first: Vec<(&str, &str)> = forge
            .checks(1)
            .iter()
            .map(|check| (check.name, check.status))
            .collect();
        assert_eq!(first, [("build", "pass"), ("lint", "fail")]);
        assert!(forge.checks(3).is_empty());
    }
}

