//! CLI-owned view data. Handlers map the forge model onto these types and the
//! framework renders them; nothing here reaches for stdout.

use serde::Serialize;

use crate::forge::{Check, PullRequest, Repository};

/// Display width of a rendered cell. Every cell in this app is ASCII, so
/// `chars().count()` is the rendered width.
fn width(cell: &str) -> usize {
    cell.chars().count()
}

#[derive(Debug, Serialize)]
pub struct AuthStatusView {
    pub username: String,
}

#[derive(Debug, Serialize)]
pub struct RepoView {
    pub name: String,
    pub description: String,
    pub visibility: String,
}

impl From<&Repository> for RepoView {
    fn from(repo: &Repository) -> Self {
        Self {
            name: repo.name.to_string(),
            description: repo.description.to_string(),
            visibility: repo.visibility.to_string(),
        }
    }
}

#[derive(Debug, Serialize)]
pub struct PrView {
    pub number: u32,
    pub title: String,
    pub state: String,
    pub author: String,
    pub draft: bool,
}

impl From<&PullRequest> for PrView {
    fn from(pr: &PullRequest) -> Self {
        Self {
            number: pr.number,
            title: pr.title.to_string(),
            state: pr.state.to_string(),
            author: pr.author.to_string(),
            draft: pr.draft,
        }
    }
}

/// Column widths for the `pr list` table, resolved from the rows the template
/// is about to render plus the header it shows. The template pads with
/// `pad_right`, the way standout's own help template aligns its sections.
#[derive(Debug, Serialize)]
pub struct PrListWidths {
    pub number: usize,
    pub title: usize,
}

#[derive(Debug, Serialize)]
pub struct PrListView {
    pub pull_requests: Vec<PrView>,
    pub widths: PrListWidths,
}

impl PrListView {
    pub fn new(pull_requests: &[PullRequest]) -> Self {
        let rows: Vec<PrView> = pull_requests.iter().map(PrView::from).collect();
        let widths = PrListWidths {
            number: rows
                .iter()
                .map(|row| width(&row.number.to_string()))
                .chain([width("NUMBER")])
                .max()
                .unwrap_or(0),
            title: rows
                .iter()
                .map(|row| width(&row.title))
                .chain([width("TITLE")])
                .max()
                .unwrap_or(0),
        };
        Self {
            pull_requests: rows,
            widths,
        }
    }
}

#[derive(Debug, Serialize)]
pub struct CheckView {
    pub name: String,
    pub status: String,
}

impl From<&Check> for CheckView {
    fn from(check: &Check) -> Self {
        Self {
            name: check.name.to_string(),
            status: check.status.to_string(),
        }
    }
}

/// The checks table is headerless, so only the rows decide its widths.
#[derive(Debug, Serialize)]
pub struct CheckListWidths {
    pub name: usize,
}

#[derive(Debug, Serialize)]
pub struct CheckListView {
    pub checks: Vec<CheckView>,
    pub widths: CheckListWidths,
}

impl CheckListView {
    pub fn new(checks: &[&Check]) -> Self {
        let rows: Vec<CheckView> = checks.iter().map(|check| CheckView::from(*check)).collect();
        let widths = CheckListWidths {
            name: rows.iter().map(|row| width(&row.name)).max().unwrap_or(0),
        };
        Self {
            checks: rows,
            widths,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::forge::Forge;

    #[test]
    fn pr_list_columns_cover_header_and_widest_cell() {
        let forge = Forge::new();
        let view = PrListView::new(forge.pull_requests());
        assert_eq!(view.widths.number, 6); // "NUMBER" is wider than any number
        assert_eq!(view.widths.title, 9); // "Add pager" is wider than "TITLE"
    }

    #[test]
    fn check_list_columns_cover_the_widest_name() {
        let forge = Forge::new();
        let view = CheckListView::new(&forge.checks(1));
        assert_eq!(view.widths.name, 5); // "build"
    }
}

