//! `Output::Binary`, which the framework writes to stdout verbatim — no
//! template, no theme, no pager, no prose. That is what keeps `--json` output
//! byte-boring even on an attended, color-capable terminal.

use anyhow::Error;
use serde::Serialize;
use serde_json::{Map, Value};
use standout::cli::{AppFailure, Output};

use crate::forge::{Check, PullRequest};

pub const PR_FIELDS: &[&str] = &["number", "title", "state", "author", "draft"];
pub const CHECK_FIELDS: &[&str] = &["name", "status"];

/// Parses a comma-separated field list, rejecting anything not on offer.
pub fn select(spec: &str, available: &[&str]) -> Result<Vec<String>, Error> {
    let mut chosen: Vec<String> = Vec::new();
    for raw in spec.split(',') {
        let field = raw.trim();
        if !available.contains(&field) {
            return Err(AppFailure::new(
                1,
                format!(
                    "ghlike: unknown JSON field: {field}\navailable fields: {}\n",
                    available.join(", ")
                ),
            )?
            .into());
        }
        if !chosen.iter().any(|already| already == field) {
            chosen.push(field.to_string());
        }
    }
    Ok(chosen)
}

pub fn pull_request(pr: &PullRequest, fields: &[String]) -> Value {
    let mut object = Map::new();
    for field in fields {
        let value = match field.as_str() {
            "number" => Value::from(pr.number),
            "title" => Value::from(pr.title),
            "state" => Value::from(pr.state),
            "author" => Value::from(pr.author),
            "draft" => Value::from(pr.draft),
            other => unreachable!("unvalidated pull request field: {other}"),
        };
        object.insert(field.clone(), value);
    }
    Value::Object(object)
}

pub fn check(check: &Check, fields: &[String]) -> Value {
    let mut object = Map::new();
    for field in fields {
        let value = match field.as_str() {
            "name" => Value::from(check.name),
            "status" => Value::from(check.status),
            other => unreachable!("unvalidated check field: {other}"),
        };
        object.insert(field.clone(), value);
    }
    Value::Object(object)
}

/// Hands the JSON document to the framework as raw bytes.
pub fn emit<T: Serialize>(document: &Value) -> Result<Output<T>, Error> {
    let mut data = serde_json::to_vec(document)?;
    data.push(b'\n');
    Ok(Output::Binary {
        data,
        filename: "ghlike.json".to_string(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::forge::Forge;

    #[test]
    fn selection_keeps_the_requested_order_and_drops_repeats() {
        let fields = select("state,number,state", PR_FIELDS).unwrap();
        assert_eq!(fields, ["state", "number"]);
    }

    #[test]
    fn an_unknown_field_names_itself_and_the_valid_ones() {
        let error = select("bogus", PR_FIELDS).unwrap_err().to_string();
        assert!(error.contains("bogus"), "{error}");
        assert!(
            error.contains("number, title, state, author, draft"),
            "{error}"
        );
    }

    #[test]
    fn typed_fields_keep_their_json_types() {
        let forge = Forge::new();
        let pr = forge.pull_request(3).unwrap();
        let fields = select("number,title,draft", PR_FIELDS).unwrap();
        let value = pull_request(pr, &fields);
        assert_eq!(value["number"], Value::from(3));
        assert_eq!(value["title"], Value::from("Docs pass"));
        assert_eq!(value["draft"], Value::from(true));
        assert_eq!(value.as_object().unwrap().len(), 3);
    }
}

