//! `ghlike` — a forge client in the gh mold.

mod forge;
mod handlers;
mod machine;
mod views;

use clap::{CommandFactory, Parser, Subcommand};
use standout::cli::{App, Dispatch};
use standout::{embed_styles, embed_templates};

use forge::Forge;

#[derive(Parser)]
#[command(name = "ghlike", about = "Work with a forge from the command line")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = crate::handlers)]
enum Commands {
    /// Authentication state
    #[command(subcommand)]
    #[dispatch(nested)]
    Auth(AuthCommands),

    /// Repositories
    #[command(subcommand)]
    #[dispatch(nested)]
    Repo(RepoCommands),

    /// Pull requests
    #[command(subcommand)]
    #[dispatch(nested)]
    Pr(PrCommands),
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = crate::handlers::auth)]
enum AuthCommands {
    /// Show who you are logged in as
    #[dispatch(pure)]
    Status,
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = crate::handlers::repo)]
enum RepoCommands {
    /// Show a repository
    #[dispatch(pure)]
    View {
        /// Repository to show
        #[arg(value_name = "OWNER/NAME")]
        repository: String,
    },
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = crate::handlers::pr)]
enum PrCommands {
    /// List pull requests
    #[dispatch(pure)]
    List {
        /// Emit JSON with the listed comma-separated fields
        #[arg(long, value_name = "FIELDS")]
        json: Option<String>,
    },

    /// Show a pull request
    #[dispatch(pure)]
    View {
        /// Pull request number
        #[arg(value_name = "NUMBER")]
        number: String,

        /// Emit JSON with the listed comma-separated fields
        #[arg(long, value_name = "FIELDS")]
        json: Option<String>,
    },

    /// Status checks
    #[command(subcommand)]
    #[dispatch(nested)]
    Checks(PrChecksCommands),
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = crate::handlers::pr::checks)]
enum PrChecksCommands {
    /// List the checks of a pull request
    #[dispatch(pure)]
    List {
        /// Pull request number
        #[arg(value_name = "NUMBER")]
        number: String,

        /// Emit JSON with the listed comma-separated fields
        #[arg(long, value_name = "FIELDS")]
        json: Option<String>,
    },
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let app = App::builder()
        .app_state(Forge::new())
        .templates(embed_templates!("src/templates"))
        .styles(embed_styles!("src/styles"))
        .default_theme("default")
        .commands(Commands::dispatch_config())?
        .build()?;

    app.verify_command(&Cli::command())?;
    app.run(Cli::command(), std::env::args());
    Ok(())
}

