//! Thin CLI adapters: read the parsed arguments, ask the forge, return view
//! data. Nothing here prints or exits.

use anyhow::Error;
use standout::cli::{AppFailure, CommandContext, Output};
use standout::handler;

use crate::forge::Forge;

fn forge(ctx: &CommandContext) -> Result<&Forge, Error> {
    ctx.app_state.get_required::<Forge>()
}

/// `<number>` is taken as text so that anything the forge does not know —
/// `9`, `x`, `-1` — is the one domain error the spec names, rather than a
/// clap type error.
fn resolve_number(forge: &Forge, number: &str) -> Result<u32, Error> {
    let found = number
        .parse::<u32>()
        .ok()
        .and_then(|number| forge.pull_request(number));
    match found {
        Some(pr) => Ok(pr.number),
        None => Err(AppFailure::new(
            1,
            format!("ghlike: no pull request found: {number}\n"),
        )?
        .into()),
    }
}

pub mod auth {
    use super::*;
    use crate::views::AuthStatusView;

    #[handler]
    pub fn status(#[ctx] ctx: &CommandContext) -> Result<Output<AuthStatusView>, Error> {
        let forge = forge(ctx)?;
        Ok(Output::Render(AuthStatusView {
            username: forge.viewer().to_string(),
        }))
    }
}

pub mod repo {
    use super::*;
    use crate::views::RepoView;

    #[handler]
    pub fn view(
        #[arg] repository: String,
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<RepoView>, Error> {
        let forge = forge(ctx)?;
        match forge.repository(&repository) {
            Some(found) => Ok(Output::Render(RepoView::from(found))),
            None => Err(AppFailure::new(
                1,
                format!("ghlike: repository not found: {repository}\n"),
            )?
            .into()),
        }
    }
}

pub mod pr {
    use super::*;
    use crate::machine;
    use crate::views::{PrListView, PrView};
    use serde_json::Value;

    #[handler]
    pub fn list(
        #[arg] json: Option<String>,
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<PrListView>, Error> {
        let forge = forge(ctx)?;
        let pull_requests = forge.pull_requests();

        if let Some(spec) = json {
            let fields = machine::select(&spec, machine::PR_FIELDS)?;
            let rows: Vec<Value> = pull_requests
                .iter()
                .map(|pr| machine::pull_request(pr, &fields))
                .collect();
            return machine::emit(&Value::Array(rows));
        }

        Ok(Output::Render(PrListView::new(pull_requests)))
    }

    #[handler]
    pub fn view(
        #[arg] number: String,
        #[arg] json: Option<String>,
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<PrView>, Error> {
        let forge = forge(ctx)?;
        let number = resolve_number(forge, &number)?;
        let pull_request = forge
            .pull_request(number)
            .expect("resolve_number returns a known number");

        if let Some(spec) = json {
            let fields = machine::select(&spec, machine::PR_FIELDS)?;
            return machine::emit(&machine::pull_request(pull_request, &fields));
        }

        Ok(Output::Render(PrView::from(pull_request)))
    }

    pub mod checks {
        use super::*;
        use crate::views::CheckListView;

        #[handler]
        pub fn list(
            #[arg] number: String,
            #[arg] json: Option<String>,
            #[ctx] ctx: &CommandContext,
        ) -> Result<Output<CheckListView>, Error> {
            let forge = forge(ctx)?;
            let number = resolve_number(forge, &number)?;
            let checks = forge.checks(number);

            if let Some(spec) = json {
                let fields = machine::select(&spec, machine::CHECK_FIELDS)?;
                let rows: Vec<Value> = checks
                    .iter()
                    .map(|check| machine::check(check, &fields))
                    .collect();
                return machine::emit(&Value::Array(rows));
            }

            Ok(Output::Render(CheckListView::new(&checks)))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use standout::cli::CommandContext;
    use std::sync::Arc;

    fn context() -> CommandContext {
        let mut state = standout::cli::Extensions::new();
        state.insert(Forge::new());
        CommandContext {
            command_path: vec!["pr".into(), "list".into()],
            app_state: Arc::new(state),
            extensions: standout::cli::Extensions::new(),
        }
    }

    #[test]
    fn pr_list_returns_every_pull_request_in_number_order() {
        let ctx = context();
        let Ok(Output::Render(view)) = pr::list(None, &ctx) else {
            panic!("expected rendered data");
        };
        let numbers: Vec<u32> = view.pull_requests.iter().map(|pr| pr.number).collect();
        assert_eq!(numbers, [1, 2, 3]);
    }

    #[test]
    fn pr_view_maps_the_requested_pull_request() {
        let ctx = context();
        let Ok(Output::Render(view)) = pr::view("2".into(), None, &ctx) else {
            panic!("expected rendered data");
        };
        assert_eq!(view.title, "Fix theme");
        assert_eq!(view.state, "merged");
        assert_eq!(view.author, "bob");
    }

    #[test]
    fn an_unknown_pull_request_is_a_domain_error() {
        let ctx = context();
        assert!(pr::view("9".into(), None, &ctx).is_err());
    }

    #[test]
    fn an_unknown_repository_is_a_domain_error() {
        let ctx = context();
        assert!(repo::view("demo/gamma".into(), &ctx).is_err());
    }

    #[test]
    fn checks_list_is_empty_for_a_pull_request_without_checks() {
        let ctx = context();
        let Ok(Output::Render(view)) = pr::checks::list("3".into(), None, &ctx) else {
            panic!("expected rendered data");
        };
        assert!(view.checks.is_empty());
    }

    #[test]
    fn json_selection_bypasses_the_render_path() {
        let ctx = context();
        let Ok(Output::Binary { data, .. }) = pr::list(Some("number,state".into()), &ctx) else {
            panic!("expected raw bytes");
        };
        assert_eq!(
            String::from_utf8(data).unwrap(),
            "[{\"number\":1,\"state\":\"open\"},\
             {\"number\":2,\"state\":\"merged\"},\
             {\"number\":3,\"state\":\"open\"}]\n"
        );
    }

    #[test]
    fn auth_status_names_the_viewer() {
        let ctx = context();
        let Ok(Output::Render(view)) = auth::status(&ctx) else {
            panic!("expected rendered data");
        };
        assert_eq!(view.username, "corpus-bot");
    }
}

