/// Full-pipeline tests: argv in, rendered bytes out, no subprocess. These pin
/// the byte-exact contract the spec states for each command.
#[cfg(test)]
mod cli_tests {
    use super::*;
    use standout_test::TestHarness;

    fn run(args: &[&str]) -> standout_test::TestResult {
        let app = app().expect("the app builds");
        let mut argv = vec!["ghlike"];
        argv.extend_from_slice(args);
        TestHarness::new().no_color().run(&app, Cli::command(), argv)
    }

    #[test]
    fn auth_status_names_the_logged_in_user() {
        run(&["auth", "status"]).assert_stdout_eq("Logged in as corpus-bot");
    }

    #[test]
    fn repo_view_shows_name_description_and_visibility() {
        run(&["repo", "view", "demo/alpha"])
            .assert_stdout_eq("demo/alpha\nAlpha service\nvisibility: public");
        run(&["repo", "view", "demo/beta"])
            .assert_stdout_eq("demo/beta\nBeta tools\nvisibility: private");
    }

    #[test]
    fn pr_list_pads_every_column_but_the_last() {
        run(&["pr", "list"]).assert_stdout_eq(
            "NUMBER TITLE     STATE\n\
             1      Add pager open\n\
             2      Fix theme merged\n\
             3      Docs pass open",
        );
    }

    #[test]
    fn pr_view_shows_one_pull_request() {
        run(&["pr", "view", "2"]).assert_stdout_eq("#2 Fix theme\nstate: merged\nauthor: bob");
    }

    #[test]
    fn pr_checks_list_is_headerless() {
        run(&["pr", "checks", "list", "1"]).assert_stdout_eq("build pass\nlint  fail");
        run(&["pr", "checks", "list", "2"]).assert_stdout_eq("build pass\nlint  pass");
        run(&["pr", "checks", "list", "3"]).assert_stdout_eq("");
    }

    #[test]
    fn unknown_repository_is_a_domain_error() {
        let result = run(&["repo", "view", "demo/gamma"]);
        result.assert_stdout_eq("");
        assert_eq!(
            result.error(),
            Some("ghlike: repository not found: demo/gamma\n")
        );
        assert_eq!(result.exit_status().unwrap().code(), 1);
    }

    #[test]
    fn unknown_pull_request_is_a_domain_error() {
        let result = run(&["pr", "view", "9"]);
        result.assert_stdout_eq("");
        assert_eq!(result.error(), Some("ghlike: no pull request found: 9\n"));
        assert_eq!(result.exit_status().unwrap().code(), 1);
    }

    #[test]
    fn an_unknown_json_field_is_a_domain_error() {
        let result = run(&["pr", "list", "--json", "bogus"]);
        result.assert_stdout_eq("");
        assert_eq!(
            result.error(),
            Some(
                "ghlike: unknown JSON field: bogus\n\
                 available fields: number, title, state, author, draft\n"
            )
        );
        assert_eq!(result.exit_status().unwrap().code(), 1);
    }

    #[test]
    fn a_group_without_a_subcommand_is_a_usage_error() {
        for group in [
            vec!["auth"],
            vec!["repo"],
            vec!["pr"],
            vec!["pr", "checks"],
        ] {
            let result = run(&group);
            result.assert_stdout_eq("");
            assert_eq!(
                result.exit_status().unwrap().code(),
                2,
                "group {group:?} should be a usage error"
            );
        }
    }

    #[test]
    fn help_works_at_every_level_and_succeeds() {
        for args in [
            vec!["--help"],
            vec!["auth", "--help"],
            vec!["auth", "status", "--help"],
            vec!["repo", "view", "--help"],
            vec!["pr", "--help"],
            vec!["pr", "list", "--help"],
            vec!["pr", "checks", "--help"],
            vec!["pr", "checks", "list", "--help"],
        ] {
            let result = run(&args);
            assert_eq!(
                result.exit_status().unwrap().code(),
                0,
                "{args:?} should succeed"
            );
            assert!(!result.stdout().is_empty(), "{args:?} should print help");
        }
    }
}

