/// `--json` never reaches the template, the theme, or a pager: the bytes
/// the framework writes are the JSON document and nothing else. The
/// harness is run `with_color()` here to prove that holds on an attended,
/// color-capable terminal.
#[test]
fn json_output_is_the_document_and_nothing_else() {
    let app = app().expect("the app builds");
    let result = TestHarness::new().with_color().run(
        &app,
        Cli::command(),
        ["ghlike", "pr", "list", "--json", "number,state"],
    );
    let (bytes, _) = result.binary().expect("json output is raw bytes");
    assert_eq!(
        String::from_utf8(bytes.to_vec()).unwrap(),
        "[{\"number\":1,\"state\":\"open\"},\
         {\"number\":2,\"state\":\"merged\"},\
         {\"number\":3,\"state\":\"open\"}]\n"
    );
}

#[test]
fn json_field_selection_carries_exactly_the_requested_fields() {
    let result = run(&["pr", "view", "3", "--json", "draft,number"]);
    let (bytes, _) = result.binary().expect("json output is raw bytes");
    assert_eq!(
        String::from_utf8(bytes.to_vec()).unwrap(),
        "{\"draft\":true,\"number\":3}\n"
    );

    let result = run(&["pr", "checks", "list", "1", "--json", "name,status"]);
    let (bytes, _) = result.binary().expect("json output is raw bytes");
    assert_eq!(
        String::from_utf8(bytes.to_vec()).unwrap(),
        "[{\"name\":\"build\",\"status\":\"pass\"},\
         {\"name\":\"lint\",\"status\":\"fail\"}]\n"
    );
}

